    float parte = maximo <= 0 ? 0 : (valor < 0 ? 0 : valor > maximo ? maximo : valor) / maximo;
    uint8_t lleno = uint8_t(126 * parte);
    uint8_t columnas[16];
    oled_ir(uint8_t(pagina), 0);
    for (uint8_t x = 0; x < 128; x += 16) {
        for (uint8_t k = 0; k < 16; k++) {
            uint8_t c = x + k;
            columnas[k] = (c == 0 || c == 127 || c <= lleno) ? 0x7E : 0x42;
        }
        oled_datos(columnas, 16);
    }
}

