static TwoWire* oled_bus = nullptr;
static uint8_t oled_direccion = 0x3C;
static uint8_t oled_desfase = 0;
static uint8_t oled_filas = 8;
inline bool oled_comandos(const uint8_t* datos, uint8_t cantidad) {
    oled_bus->beginTransmission(oled_direccion);
    oled_bus->write(uint8_t(0x00));
    for (uint8_t i = 0; i < cantidad; i++) oled_bus->write(datos[i]);
    return oled_bus->endTransmission() == 0;
}
inline void oled_ir(uint8_t pagina, uint8_t x) {
    uint8_t columna = x + oled_desfase;
    uint8_t datos[3] = {uint8_t(0xB0 | pagina), uint8_t(columna & 0x0F), uint8_t(0x10 | (columna >> 4))};
    oled_comandos(datos, 3);
}
// Bytes de imagen en trozos de 16: el búfer de Wire del UNO es de 32.
inline void oled_datos(const uint8_t* datos, uint8_t cantidad) {
    for (uint8_t inicio = 0; inicio < cantidad; inicio += 16) {
        oled_bus->beginTransmission(oled_direccion);
        oled_bus->write(uint8_t(0x40));
        for (uint8_t i = inicio; i < cantidad && i < inicio + 16; i++) oled_bus->write(datos[i]);
        oled_bus->endTransmission();
    }
}
inline void oled_vacio(uint8_t cantidad) {
    uint8_t ceros[16] = {0};
    while (cantidad > 0) {
        uint8_t trozo = cantidad < 16 ? cantidad : 16;
        oled_datos(ceros, trozo);
        cantidad -= trozo;
    }
}
inline bool oled_activa(const char* bloque) {
    if (oled_bus) return true;
    rb_fail(bloque, "Configura la pantalla OLED al iniciar");
    return false;
}
inline void oled_borrar(const char* bloque) {
    if (!oled_activa(bloque)) return;
    for (uint8_t pagina = 0; pagina < oled_filas; pagina++) {
        oled_ir(pagina, 0);
        oled_vacio(128);
    }
}
inline void oled_configurar(TwoWire& bus, const String& direccion, const String& chip, const String& alto, const char* bloque) {
    oled_bus = &bus;
    oled_direccion = direccion == "0x3D" ? 0x3D : 0x3C;
    bool sh1106 = chip == "sh1106";
    oled_desfase = sh1106 ? 2 : 0;
    oled_filas = alto == "32" ? 4 : 8;
    const uint8_t comunes[] = {0xAE, 0xD5, 0x80, 0xA8, uint8_t(oled_filas * 8 - 1), 0xD3, 0x00, 0x40, 0xA1, 0xC8, 0xDA, uint8_t(oled_filas == 4 ? 0x02 : 0x12), 0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6};
    const uint8_t bomba_ssd1306[] = {0x8D, 0x14, 0x20, 0x02};
    const uint8_t bomba_sh1106[] = {0xAD, 0x8B};
    const uint8_t encender = 0xAF;
    if (!oled_comandos(comunes, sizeof(comunes))) {
        oled_bus = nullptr;
        rb_fail(bloque, "No responde la pantalla OLED (0x3C/0x3D)");
        return;
    }
    if (sh1106) oled_comandos(bomba_sh1106, sizeof(bomba_sh1106));
    else oled_comandos(bomba_ssd1306, sizeof(bomba_ssd1306));
    oled_borrar(bloque);
    oled_comandos(&encender, 1);
}
inline uint8_t oled_glifo(uint8_t letra) {
    if (letra >= 'a' && letra <= 'z') letra -= 32;
    return letra >= 32 && letra <= 95 ? letra - 32 : 31;
}
// Lee una letra UTF-8: vocales con tilde y ñ usan la letra sin tilde; °, ¡ y ¿ tienen glifo.
inline uint8_t oled_utf8(const String& texto, unsigned int& i) {
    uint8_t primero = uint8_t(texto[i++]);
    if (primero < 0x80) return oled_glifo(primero);
    uint8_t segundo = i < texto.length() ? uint8_t(texto[i]) : 0;
    while (i < texto.length() && (uint8_t(texto[i]) & 0xC0) == 0x80) i++;
    if (primero == 0xC2) return segundo == 0xB0 ? 64 : segundo == 0xA1 ? 65 : segundo == 0xBF ? 66 : 31;
    if (primero != 0xC3) return 31;
    switch (segundo | 0x20) {
        case 0xA1: return 'A' - 32;
        case 0xA9: return 'E' - 32;
        case 0xAD: return 'I' - 32;
        case 0xB3: return 'O' - 32;
        case 0xBA: return 'U' - 32;
        case 0xBC: return 'U' - 32;
        case 0xB1: return 'N' - 32;
        default: return 31;
    }
}
inline String oled_texto(const String& valor) {
    return valor;
}
inline String oled_texto(const char* valor) {
    return String(valor);
}
inline String oled_texto(bool valor) {
    return valor ? String("verdadero") : String("falso");
}
inline String oled_texto(long valor) {
    char texto[16];
    snprintf(texto, sizeof(texto), "%ld", valor);
    return String(texto);
}
inline String oled_texto(int valor) {
    return oled_texto(long(valor));
}
// Números con hasta 2 decimales y sin ceros al final (printf de AVR no imprime float).
inline String oled_texto(double valor) {
    if (valor == double(long(valor)) && fabs(valor) < 10000000.0) return oled_texto(long(valor));
    long centesimas = long(fabs(valor) * 100.0 + 0.5);
    char texto[20];
    snprintf(texto, sizeof(texto), "%s%ld.%02ld", valor < 0 ? "-" : "", centesimas / 100, centesimas % 100);
    size_t largo = strlen(texto);
    while (largo > 0 && texto[largo - 1] == '0') texto[--largo] = 0;
    if (largo > 0 && texto[largo - 1] == '.') texto[--largo] = 0;
    return String(texto);
}
inline String oled_texto(float valor) {
    return oled_texto(double(valor));
}
inline int oled_pagina(float fila, const char* bloque) {
    if (!(fila >= 1 && fila <= oled_filas && fila == float(int(fila)))) {
        rb_fail(bloque, "Fila de OLED fuera de la pantalla");
        return -1;
    }
    return int(fila) - 1;
}
inline uint8_t oled_escribir_en(uint8_t pagina, uint8_t columna, const String& texto) {
    oled_ir(pagina, columna * 8);
    unsigned int i = 0;
    uint8_t celda[8] = {0};
    while (i < texto.length() && columna < 16) {
        uint8_t glifo = oled_utf8(texto, i);
        for (uint8_t k = 0; k < 5; k++) celda[k + 1] = OLED_LEER(&oled_fuente[glifo][k]);
        oled_datos(celda, 8);
        columna++;
    }
    return columna;
}
inline void oled_borrar_fila(float fila, const char* bloque) {
    if (!oled_activa(bloque)) return;
    int pagina = oled_pagina(fila, bloque);
    if (pagina < 0) return;
    oled_ir(uint8_t(pagina), 0);
    oled_vacio(128);
}
inline void oled_escribir(const String& texto, float fila, float columna, const char* bloque) {
    if (!oled_activa(bloque)) return;
    int pagina = oled_pagina(fila, bloque);
    if (pagina < 0) return;
    if (!(columna >= 1 && columna <= 16 && columna == float(int(columna)))) {
        rb_fail(bloque, "Columna de OLED fuera de la pantalla (1–16)");
        return;
    }
    oled_escribir_en(uint8_t(pagina), uint8_t(columna) - 1, texto);
}
inline void oled_mostrar(float fila, const String& texto, const char* bloque) {
    if (!oled_activa(bloque)) return;
    int pagina = oled_pagina(fila, bloque);
    if (pagina < 0) return;
    uint8_t final = oled_escribir_en(uint8_t(pagina), 0, texto);
    oled_vacio(uint8_t(8 * (16 - final)));
}
inline void oled_barra(float fila, float valor, float maximo, const char* bloque) {
    if (!oled_activa(bloque)) return;
    int pagina = oled_pagina(fila, bloque);
    if (pagina < 0) return;
    float parte = maximo <= 0 ? 0 : (valor < 0 ? 0 : valor > maximo ? maximo : valor) / maximo;
    uint8_t lleno = uint8_t(126 * parte);
    uint8_t columnas[16];
    oled_ir(uint8_t(pagina), 0);
    for (uint8_t x = 0; x < 128; x += 16) {
        for (uint8_t k = 0; k < 16; k++) {
            uint8_t c = x + k;
            columnas[k] = (c == 0 || c == 127 || c <= lleno) ? 0x7E : 0x42;
        }
        oled_datos(columnas, 16);
    }
}
